def knapsack(weights, values, capacity):
    best = [0] * (capacity + 1)          # best[c]: the most value that fits in capacity c
    for weight, value in zip(weights, values):
        for c in range(capacity, weight - 1, -1):      # downwards, so this item is used at most once
            best[c] = max(best[c], best[c - weight] + value)
    return best[capacity]
